@DoNotInline public static AudioOffloadSupport getOffloadedPlaybackSupport(AudioFormat audioFormat,android.media.AudioAttributes audioAttributes,boolean isOffloadVariableRateSupported){
  if (!AudioManager.isOffloadedPlaybackSupported(audioFormat,audioAttributes)) {
    return AudioOffloadSupport.DEFAULT_UNSUPPORTED;
  }
  return new AudioOffloadSupport.Builder().setIsFormatSupported(true).setIsSpeedChangeSupported(isOffloadVariableRateSupported).setIsGaplessSupported(Util.SDK_INT == 30 && Util.MODEL.startsWith("Pixel")).build();
}
